package com.getcapacitor;
public class PluginCall {public final JSObject data;public JSObject result;public String error;public PluginCall(JSObject data){this.data=data;}public String getString(String key){return data.optString(key,null);}public String getString(String key,String fallback){return data.optString(key,fallback);}public Long getLong(String key){return data.has(key)?data.optLong(key):null;}public Boolean getBoolean(String key){return data.has(key)?data.optBoolean(key):null;}public JSObject getObject(String key){return getObject(key,null);}public JSObject getObject(String key,JSObject fallback){org.json.JSONObject value=data.optJSONObject(key);try{return value==null?fallback:new JSObject(value.toString());}catch(Exception e){throw new AssertionError(e);}}public void resolve(JSObject value){result=value;}public void reject(String value){error=value;}}
